pub fn count_uppercase(text: &Vec<char>) -> u64 {
    // Counts only ASCII uppercase letters: 'A'..='Z' (code points 65..=90).
    text.iter()
        .filter(|&&c| matches!(c, 'A'..='Z'))
        .count() as u64
}

